def main():
    import sys

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        numbers = list(map(int, line.split()))

        if numbers and numbers[-1] == -1:
            numbers = numbers[:-1]

        if not numbers:
            print("Even Sum Greater")
            continue

        odd_sum = 0
        even_sum = 0

        for num in numbers:
            if num % 2 == 0:
                even_sum += num
            else:
                odd_sum += num

        if odd_sum > even_sum:
            print("Odd Sum Greater")
        else:
            print("Even Sum Greater")

if __name__ == "__main__":
    main()
